"Auxílio": {circulo:"2º Círculo", escola:"Abjuração", classes:["Bardo", "Clérigo", "Druida", "Guardião", "Paladino"], concentracao:false, ritual:false, tempo:"Ação", alcance:"9 metros", componentes:"V, S, M (uma tira de pano branco)", duracao:"8 horas", efeito:"Até 3 criaturas: PV máximo e atual +5 pela duração (8h).", escalonamento:"Upcast: +5 PV por círculo.", pagina:"246"},
"Boca Encantada": {circulo:"2º Círculo", escola:"Ilusão", classes:["Bardo", "Mago", "Psiônico"], concentracao:false, ritual:true, tempo:"1 minuto ou Ritual", alcance:"9 metros", componentes:"V, S, M (poeira de jade no valor de 10 ou mais PO, que a magia consome)", duracao:"Até ser dissipada", efeito:"Implanta mensagem (até 25 palavras) num objeto, revelada por um gatilho visual/sonoro à sua escolha num raio de 9m do objeto. Uma boca espectral fala com sua voz quando dispara; você escolhe se repete sempre ou só uma vez. Dura até ser dissipada.", escalonamento:"—", pagina:"248"},
"Cativar": {circulo:"2º Círculo", escola:"Encantamento", classes:["Bardo", "Bruxo", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S", duracao:"Concentração, até 1 minuto", efeito:"Palavras perturbadoras contra alvos à escolha à vista. Quem já luta contra você/aliados passa automático. Salv. Sabedoria ou -10 em Percepção (teste e passiva) pela duração.", escalonamento:"—", pagina:"252"},
"Cegueira/Surdez": {circulo:"2º Círculo", escola:"Transmutação", classes:["Bardo", "Clérigo", "Feiticeiro", "Mago", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V", duracao:"1 minuto", efeito:"Salv. Constituição ou Cego/Surdo (à sua escolha) pela duração (1 min); repete a salvaguarda no fim de cada turno.", escalonamento:"Upcast: +1 alvo/círculo.", pagina:"252"},
"Chama Contínua": {circulo:"2º Círculo", escola:"Evocação", classes:["Clérigo", "Druida", "Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, S, M (rubi em pó no valor de 50 ou mais PO, que a magia consome)", duracao:"Até ser dissipada", efeito:"Toca objeto: chama fria (sem calor, não consome combustível) emite Luz Plena 6m + Meia-luz 6m, até ser dissipada. Pode ser coberta mas não apagada.", escalonamento:"—", pagina:"253"},
"Chicote Mental de Tasha": {circulo:"2º Círculo", escola:"Encantamento", classes:["Feiticeiro", "Mago", "Psiônico"], concentracao:false, ritual:false, tempo:"1 ação", alcance:"27 metros", componentes:"V", duracao:"Instantânea", efeito:"Golpe psíquico. Salv. Inteligência ou 3d6 dano Psíquico + sem Ataque de Oportunidade até o fim do próximo turno + só pode Mover OU Ação OU Ação Bônus no próximo turno (sucesso=metade do dano, sem restrição).", escalonamento:"Upcast: +1 alvo/círculo acima do 2º.", pagina:"UA-16"},
"Chicote do Ego": {circulo:"2º Círculo", escola:"Encantamento", classes:["Psiônico"], concentracao:false, ritual:false, tempo:"Reação (criatura à vista a até 9m faz teste de Carisma/salvaguarda)", alcance:"36 metros", componentes:"V", duracao:"Instantânea", efeito:"Salv. Carisma ou a criatura subtrai 1d8 do resultado do teste de atributo ou salvaguarda que estava fazendo.", escalonamento:"—", pagina:"UA-16"},
