"Destruição Radiante": {circulo:"2º Círculo", escola:"Transmutação", classes:["Paladino"], concentracao:true, ritual:false, tempo:"Ação Bônus, que você realiza imediatamente após atingir uma criatura com uma arma Corpo a Corpo ou um Ataque Desarmado", alcance:"Pessoal", componentes:"V", duracao:"Concentração, até 1 minuto", efeito:"Ação Bônus após acertar corpo a corpo/desarmado: +2d6 dano Radiante; até acabar (1 min), alvo emite Luz Plena 1,5m, sofre ataques com Vantagem e perde benefício de Invisível.", escalonamento:"Upcast: +1d6.", pagina:"271"},
"Detectar Pensamentos": {circulo:"2º Círculo", escola:"Adivinhação", classes:["Bardo", "Feiticeiro", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"Pessoal", componentes:"V, S, M (1 Peça de Cobre)", duracao:"Concentração, até 1 minuto", efeito:"2 modos, ativáveis livremente durante a duração: Sentir Pensamentos (sente mentes a 9m que conhecem idioma/são telepáticas, sem ler); Ler Pensamentos (escolhe 1 alvo, descobre o pensamento superficial; sondar mais fundo no turno seguinte força Salv. Sabedoria — falha revela raciocínio/emoções, sucesso encerra; o alvo sempre percebe que está sendo sondado e pode tentar Arcanismo pra encerrar).", escalonamento:"—", pagina:"272"},
"Encontrar Armadilhas": {circulo:"2º Círculo", escola:"Adivinhação", classes:["Clérigo", "Druida", "Guardião"], concentracao:false, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V, S", duracao:"Instantânea", efeito:"Sente qualquer armadilha (inclusive mágica, tipo Alarme/Glifo) à vista no alcance — revela que existe e a natureza geral do perigo, não a localização exata.", escalonamento:"—", pagina:"276"},
