"Escuridão": {circulo:"2º Círculo", escola:"Evocação", classes:["Bruxo", "Feiticeiro", "Mago"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, M (pelo de morcego e um pedaço de carvão)", duracao:"Concentração, até 10 minutos", efeito:"Escuridão mágica preenche esfera de 4,5m (ou Emanação de 4,5m num objeto, bloqueável cobrindo o objeto). Visão no Escuro não penetra; luz não-mágica não ilumina. Dissipa magias de Luz de 2º círculo ou menor sobrepostas.", escalonamento:"—", pagina:"278"},
