"Contramagia": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bruxo", "Feiticeiro", "Mago"], concentracao:false, ritual:false, tempo:"Reação, que você executa quando vê uma criatura a até 18 metros de você conjurando uma magia com componentes Verbais, Somáticos ou Materiais", alcance:"18 metros", componentes:"S", duracao:"Instantânea", efeito:"Reação ao ver alguém a até 18m conjurando (com componente V/S/M): Salv. Constituição do conjurador ou a magia dele se dissipa sem efeito (ação/espaço desperdiçados).", escalonamento:"—", pagina:"258"},
