"Convocar Relâmpagos": {circulo:"3º Círculo", escola:"Invocação", classes:["Druida"], concentracao:true, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V, S", duracao:"Concentração, até 10 minutos", efeito:"Nuvem de tempestade (cilindro 3m alt x18m raio) acima de um ponto à vista. A cada conjuração (e Ação de Usar Magia em turnos seguintes): escolhe ponto sob a nuvem — quem estiver a 1,5m: Salv. Destreza ou 3d10 Elétrico (sucesso=metade). Se ao ar livre durante tempestade real: controla ela, +1d10 de dano.", escalonamento:"Upcast: +1d10.", pagina:"263"},
"Crescimento de Plantas": {circulo:"3º Círculo", escola:"Transmutação", classes:["Bardo", "Druida", "Guardião"], concentracao:false, ritual:false, tempo:"Ação (Crescimento Excessivo) ou 8 horas (Fertilização)", alcance:"45 metros", componentes:"V, S", duracao:"Instantânea", efeito:"Ação (Crescimento Excessivo): esfera de 30m vira Terreno Difícil intenso (4m de deslocamento por 1m andado); pode isentar áreas. OU 8h (Fertilização): plantas num raio de 800m dobram produção por 365 dias (só 1x/ano).", escalonamento:"—", pagina:"264"},
"Criar Comida e Água": {circulo:"3º Círculo", escola:"Invocação", classes:["Clérigo", "Paladino"], concentracao:false, ritual:false, tempo:"Ação", alcance:"9 metros", componentes:"V, S", duracao:"Instantânea", efeito:"Cria 20kg de comida + 120L de água potável no alcance. Comida não temperada mas nutritiva; estraga em 24h.", escalonamento:"—", pagina:"265"},
"Círculo Mágico": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bruxo", "Clérigo", "Mago", "Paladino"], concentracao:false, ritual:false, tempo:"1 minuto", alcance:"3 metros", componentes:"V, S, M (sal e prata em pó no valor de 100 ou mais PO, que a magia consome)", duracao:"1 hora", efeito:"Cilindro de 3m raio x6m altura. Escolha 1+ tipos (Celestial/Elemental/Feérico/Ínfero/Morto-vivo): não entram voluntariamente (teleporte requer Salv. Carisma), têm Desvantagem atacando quem está dentro, não podem possuir/amedrontar/enfeitiçar quem está dentro. Pode inverter (protege quem está fora). Dura 1h.", escalonamento:"Upcast: +1h/círculo.", pagina:"254"},
"Destruição Cegante": {circulo:"3º Círculo", escola:"Evocação", classes:["Paladino"], concentracao:false, ritual:false, tempo:"Ação Bônus, que você realiza imediatamente após atingir uma criatura com uma arma Corpo a Corpo ou um Ataque Desarmado", alcance:"Pessoal", componentes:"V", duracao:"1 minuto", efeito:"Ação Bônus após acertar corpo a corpo/desarmado: +3d8 dano Radiante + Cego até acabar (Salv. Constituição no fim de cada turno dele pra encerrar, 1 min).", escalonamento:"Upcast: +1d8.", pagina:"270"},
"Dissipar Magia": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bardo", "Bruxo", "Clérigo", "Druida", "Feiticeiro", "Guardião", "Mago", "Paladino", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V, S", duracao:"Instantânea", efeito:"Encerra automaticamente qualquer magia ativa de 3º círculo ou menor no alvo. Pra cada uma de 4º+: teste do seu atributo de conjuração (CD 10+círculo da magia alvo) — sucesso encerra.", escalonamento:"Upcast: encerra automático até o círculo do espaço usado.", pagina:"273"},
"Escuridão Sangrenta": {circulo:"3º Círculo", escola:"Evocação", classes:["Bruxo", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S, M (frasco de tinta rara, 50+ PO)", duracao:"Concentração, até 1 minuto", efeito:"Cria esfera de tinta negra (3m raio) que jorra escuridão mágica formando cilindro (3m raio x12m altura) até seu próximo turno — Terreno Difícil, bloqueia toda luz. Ao surgir e ao entrar/terminar turno lá (1x/turno): Salv. Constituição ou 3d8 dano Gélido + Cego até o fim do próximo turno (sucesso=metade, sem Cego). Ação de Usar Magia move a esfera até 6m, renovando a escuridão.", escalonamento:"Upcast: +1d8.", pagina:"UA-18"},
"Esmagamento Telecinético": {circulo:"3º Círculo", escola:"Transmutação", classes:["Bruxo", "Feiticeiro", "Psiônico"], concentracao:false, ritual:false, tempo:"1 ação", alcance:"36 metros", componentes:"V", duracao:"Instantânea", efeito:"Campo de força esmagador num cubo de 9m. Salv. Força ou 5d6 dano de Força + Caído (sucesso=metade, sem Caído).", escalonamento:"Upcast: +1d6.", pagina:"UA-18"},
"Falar com Mortos": {circulo:"3º Círculo", escola:"Necromancia", classes:["Bardo", "Clérigo", "Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"3 metros", componentes:"V, S, M (um incenso aceso)", duracao:"10 minutos", efeito:"Dá aparência de vida a um cadáver (com boca), permite até 5 perguntas na duração (10 min). Só sabe o que sabia em vida; respostas curtas/enigmáticas, pode mentir se hostil a você. Falha se já foi Morto-vivo ou já foi alvo dessa magia nos últimos 10 dias.", escalonamento:"—", pagina:"282"},
"Falar com Plantas": {circulo:"3º Círculo", escola:"Transmutação", classes:["Bardo", "Druida", "Guardião"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Pessoal", componentes:"V, S", duracao:"10 minutos", efeito:"Emanação imóvel de 9m: plantas ganham razão limitada, comunicam-se com você, seguem comandos simples, informam eventos das últimas 24h na área. Pode alternar Terreno Difícil vegetal ↔ normal na área, pela duração (10 min).", escalonamento:"—", pagina:"282"},
"Flecha Relâmpago": {circulo:"3º Círculo", escola:"Transmutação", classes:["Guardião"], concentracao:false, ritual:false, tempo:"Ação Bônus, que você realiza imediatamente após atingir ou errar um alvo com um ataque à distância usando uma arma", alcance:"Pessoal", componentes:"V, S", duracao:"Instantânea", efeito:"Ação Bônus após acertar/errar um ataque à distância com arma: vira relâmpago — 4d8 Elétrico no acerto (metade no erro), + quem estiver a 3m do alvo: Salv. Destreza ou 2d8 Elétrico (sucesso=metade).", escalonamento:"Upcast: +1d8 em ambos.", pagina:"282"},
"Fome de Hadar": {circulo:"3º Círculo", escola:"Invocação", classes:["Bruxo"], concentracao:true, ritual:false, tempo:"Ação", alcance:"45 metros", componentes:"V, S, M (um tentáculo em conserva)", duracao:"Concentração, até 1 minuto", efeito:"Esfera de Escuridão de 6m (Terreno Difícil, sons estranhos audíveis a 9m, Cego pra quem está totalmente dentro, nenhuma luz ilumina). Quem começa turno lá: 2d6 Gélido; quem termina turno lá: Salv. Destreza ou 2d6 Ácido.", escalonamento:"—", pagina:"283"},
