"Fortaleza Mental": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bardo", "Bruxo", "Feiticeiro", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"1 ação", alcance:"9 metros", componentes:"V", duracao:"Concentração, até 1 hora", efeito:"Toca criatura voluntária à vista: Resistência a dano Psíquico + Vantagem em salvaguardas de Inteligência, Sabedoria e Carisma, pela duração.", escalonamento:"Upcast: +1 alvo/círculo acima do 3º.", pagina:"UA-18"},
