"Imagem Maior": {circulo:"3º Círculo", escola:"Ilusão", classes:["Bardo", "Bruxo", "Feiticeiro", "Mago"], concentracao:true, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V, S, M (um pouco de lã)", duracao:"Concentração, até 10 minutos", efeito:"Ilusão completa (som/cheiro/temperatura) até cubo de 6m, movível por Ação de Usar Magia com narração de movimento natural. Interação física ou Investigação vs sua CD revela. Dura 10 min de Concentração; upcast com espaço 4º+: dura até dissipar, sem Concentração.", escalonamento:"—", pagina:"288"},
"Indetectável": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bardo", "Guardião", "Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, S, M (uma pitada de poeira de diamante no valor de 25 ou mais PO, que a magia consome)", duracao:"8 horas", efeito:"Toca (criatura/local/objeto até 3m): protegido de magias e sensores de Adivinhação, pela duração (8h).", escalonamento:"—", pagina:"289"},
