"Luz do Dia": {circulo:"3º Círculo", escola:"Evocação", classes:["Clérigo", "Druida", "Feiticeiro", "Guardião", "Paladino"], concentracao:false, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S", duracao:"1 hora", efeito:"Luz do sol preenche esfera de 18m (Luz Plena) + Meia-luz por mais 18m, pela duração (1h). Dissipa Escuridão de 3º círculo ou menor sobreposta.", escalonamento:"—", pagina:"300"},
"Línguas": {circulo:"3º Círculo", escola:"Adivinhação", classes:["Bardo", "Bruxo", "Clérigo", "Feiticeiro", "Mago", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, M (um zigurate em miniatura)", duracao:"1 hora", efeito:"Toca: entende qualquer idioma falado/em sinais que ouça/veja; quando ele fala/sinaliza, qualquer um que saiba 1 idioma o entende, pela duração (1h).", escalonamento:"—", pagina:"298"},
