"Palavra Curativa em Massa": {circulo:"3º Círculo", escola:"Abjuração", classes:["Bardo", "Clérigo"], concentracao:false, ritual:false, tempo:"Ação Bônus", alcance:"18 metros", componentes:"V", duracao:"Instantânea", efeito:"Ação Bônus à distância: até 6 criaturas curam 2d4 + mod. conjuração PV.", escalonamento:"Upcast: +1d4.", pagina:"314"},
