"Proteção Contra Energia": {circulo:"3º Círculo", escola:"Abjuração", classes:["Clérigo", "Druida", "Feiticeiro", "Guardião", "Mago"], concentracao:true, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, S", duracao:"Concentração, até 1 hora", efeito:"Toca: Resistência a 1 tipo (Ácido/Elétrico/Gélido/Ígneo/Trovejante) à escolha, pela duração (1h).", escalonamento:"—", pagina:"320"},
