"Respirar na Água": {circulo:"3º Círculo", escola:"Transmutação", classes:["Druida", "Feiticeiro", "Guardião", "Mago"], concentracao:false, ritual:true, tempo:"Ação ou Ritual", alcance:"9 metros", componentes:"V, S, M (um pedaço de junco)", duracao:"24 horas", efeito:"Até 10 voluntários respiram debaixo d'água (mantendo respiração normal também), por 24h.", escalonamento:"—", pagina:"327"},
